import os
os.environ['OPENBLAS_NUM_THREADS']='1';os.environ['OMP_NUM_THREADS']='1'
from pathlib import Path
import numpy as np,json
code='''import numpy as np
PERM=np.array([3,7,13,2,14,6,0,1,5,10,8,12,15,4,11,9])
def sigmoid(x):
 return 1/(1+np.exp(-np.clip(x,-40,40)))
def softmax(x):
 q=np.exp(x-x.max(-1,keepdims=True));return q/q.sum(-1,keepdims=True)
def features(X, lags=(), pos=True):
 n=X.shape[0];t=np.broadcast_to(np.arange(4,24),(n,20)); parts=[np.ones((n*20,1)),np.eye(16)[X[:,:20]].reshape(-1,16)]
 if pos: parts.append(np.eye(20)[t-4].reshape(-1,20))
 for lag in lags:
  valid=t>=lag;tok=np.zeros((n,20),int);rows=np.broadcast_to(np.arange(n)[:,None],t.shape);tok[valid]=X[rows[valid],(t-lag)[valid]]
  parts.append((np.eye(16)[tok]*valid[...,None]).reshape(-1,16))
 return np.concatenate(parts,1)
def fit(a,y,lam=1):
 r=np.eye(a.shape[1])*lam;r[0,0]=1e-9
 return np.linalg.solve(a.T@a+r,a.T@y)
def decompose(X,P):
 mode=PERM[X[:,:20]].ravel();p=P[:,4:].reshape(-1,16);m=p[np.arange(len(mode)),mode];off=p/(1-m[:,None]);off[np.arange(len(mode)),mode]=0
 # The missing entry is unobserved, not an actual zero-probability off-mode outcome.
 return mode,m,off
def metrics(q,p):
 return [float(np.mean(np.sum(p*np.log(p/np.maximum(q,1e-15)),-1))),float(np.sqrt(np.mean((p-q)**2))),float(np.mean(np.abs(p-q).sum(-1)/2))]
def masked_softmax(z,mode):
 z=z.copy();z[np.arange(len(mode)),mode]=-1000;return softmax(z)
'''
Path('/output/calibrate.py').write_text(code)
exec(code)
D=np.load('/challenge/observations.npz');X=D['tokens'];P=D['probabilities'];tr=np.arange(96);te=np.arange(96,128)
mode,m,off=decompose(X,P);lm=np.log(m/(1-m)); mode=mode.reshape(128,20);m=m.reshape(128,20);lm=lm.reshape(128,20);off=off.reshape(128,20,16)
records=[]
for lags in [(),(1,),(1,3),(1,3,7),(1,2,3,5,6,7),(1,2,3,5,6,7,8,9,10,11,12)]:
 a=features(X[tr],lags);b=features(X[te],lags)
 for lam in [0.01,0.1,1,10]:
  wm=fit(a,lm[tr].ravel(),lam);qmode=sigmoid(b@wm)
  # Off-distribution regression separately for each output, excluding its modal rows.
  wo=np.empty((a.shape[1],16));targets=np.log(np.maximum(off[tr].reshape(-1,16),1e-30));targets-=np.where(off[tr].reshape(-1,16)>0,targets,0).sum(-1,keepdims=True)/15
  for j in range(16):
   keep=mode[tr].ravel()!=j;wo[:,j]=fit(a[keep],targets[keep,j],lam)
  qo=masked_softmax(b@wo,mode[te].ravel());q=qo*(1-qmode[:,None]);q[np.arange(len(q)),mode[te].ravel()]=qmode
  met=metrics(q.reshape(32,20,16),P[te,4:]);records.append({'lags':lags,'ridge':lam,'metrics':met,'parameters':int(wm.size+wo.size)})
 print('decomp',lags,[(r['ridge'],np.round(r['metrics'],7).tolist()) for r in records[-4:]])
print('best',sorted(records,key=lambda r:r['metrics'][0])[:6])
